#include <stdio.h>

int dp[10005];

int main() {
    int n, amount;
    if (scanf("%d %d", &n, &amount) != 2) return 0;
    int coins[20];
    for (int i = 0; i < n; i++) scanf("%d", &coins[i]);
    for (int i = 1; i <= amount; i++) dp[i] = 1000000;
    dp[0] = 0;
    for (int i = 0; i < n; i++) {
        int c = coins[i];
        for (int j = c; j <= amount; j++) {
            if (dp[j - c] + 1 < dp[j]) {
                dp[j] = dp[j - c] + 1;
            }
        }
    }
    printf("%d\n", dp[amount] >= 1000000 ? -1 : dp[amount]);
    return 0;
}
